/** CADX brand — raster assets generated by scripts/make_brand_assets.py
 *  from the source PNGs. `wordmark` renders the full CAD+X lockup
 *  (transparent background), otherwise the rounded app-icon tile. */
export default function Logo({
  size = 20,
  wordmark = false,
  className = "",
}: {
  size?: number;
  wordmark?: boolean;
  className?: string;
}) {
  if (wordmark) {
    // the wordmark PNG carries glow margins — render a bit taller than the
    // nominal size so it matches the old text+mark lockup visually.
    // inline style: Tailwind preflight (img{height:auto}) would otherwise
    // override the height attribute
    return (
      <img
        src="/brand/wordmark.png"
        alt="CADX"
        style={{ height: Math.round(size * 1.5), width: "auto" }}
        className={className}
      />
    );
  }
  return (
    <img
      src="/brand/icon.png"
      alt="CADX"
      style={{ width: size, height: size }}
      className={`rounded-md ${className}`}
    />
  );
}
